/* ─── GLASS LOGO ─── */
/* The key: logo gets a colored glow behind it that changes per context */
function GlowLogo({ size = 140, glow = "green", style: s = {} }) {
  /* Pixel-measured from the 500x500 source image:
     Circle mark center: (50.4%, 36.8%) of image
     Circle diameter: 45.5% of image
     These values position the glow halo exactly on the circle outline. */
  const d = size * 0.455;           /* glow diameter matches circle */
  const glowTop = size * 0.14;      /* 14% from top = circle top edge */
  const glowLeft = size * 0.276;    /* 27.6% from left = circle left edge */

  const glows = {
    green: `0 0 ${d*0.35}px rgba(45,139,85,0.45), 0 0 ${d*0.8}px rgba(26,107,74,0.18), 0 0 ${d*1.2}px rgba(26,107,74,0.06)`,
    blue: `0 0 ${d*0.35}px rgba(59,130,200,0.5), 0 0 ${d*0.8}px rgba(37,99,168,0.22), 0 0 ${d*1.2}px rgba(91,160,212,0.08)`,
    gold: `0 0 ${d*0.35}px rgba(212,165,74,0.45), 0 0 ${d*0.8}px rgba(200,173,126,0.2), 0 0 ${d*1.2}px rgba(200,173,126,0.06)`,
    night: `0 0 ${d*0.3}px rgba(180,200,220,0.3), 0 0 ${d*0.6}px rgba(147,197,232,0.15), 0 0 ${d*1.0}px rgba(91,160,212,0.08), 0 0 ${d*1.5}px rgba(200,220,240,0.04)`,
    white: `0 0 ${d*0.35}px rgba(255,255,255,0.55), 0 0 ${d*0.8}px rgba(255,255,255,0.22), 0 0 ${d*1.2}px rgba(255,255,255,0.07)`,
  };
  const filters = {
    green: "brightness(1.1) drop-shadow(0 0 12px rgba(45,139,85,0.3))",
    blue: "brightness(1.15) drop-shadow(0 0 14px rgba(59,130,200,0.35))",
    gold: "brightness(1.15) drop-shadow(0 0 12px rgba(212,165,74,0.3))",
    night: "brightness(1.35) contrast(1.05) drop-shadow(0 0 14px rgba(147,197,232,0.3))",
    white: "brightness(1.2) drop-shadow(0 0 14px rgba(255,255,255,0.4))",
  };

  return (
    <div style={{ position: "relative", display: "inline-block", ...s }}>
      {/* Glow halo — pixel-matched to the circle mark outline */}
      <div style={{
        position: "absolute",
        top: glowTop,
        left: glowLeft,
        width: d,
        height: d,
        borderRadius: "50%",
        boxShadow: glows[glow] || glows.green,
        background: "transparent",
        pointerEvents: "none",
      }} />
      <img src={LOGO} alt="OAISIS" style={{
        width: size, height: size, objectFit: "contain", position: "relative",
        filter: filters[glow] || filters.green,
      }} />
    </div>
  );
}

/* ─── GLASS CARD ─── */
function Glass({ children, style = {}, variant = "default" }) {
  const variants = {
    default: {
      background: "rgba(255,255,255,0.48)",
      border: "1px solid rgba(255,255,255,0.7)",
      boxShadow: "0 4px 20px rgba(0,0,0,0.04), inset 0 1px 0 rgba(255,255,255,0.5)",
    },
    tan: {
      background: "rgba(237,226,204,0.4)",
      border: "1px solid rgba(220,201,160,0.5)",
      boxShadow: "0 4px 20px rgba(160,128,80,0.06), inset 0 1px 0 rgba(255,255,255,0.4)",
    },
    green: {
      background: "rgba(26,107,74,0.05)",
      border: "1px solid rgba(26,107,74,0.12)",
      boxShadow: "0 4px 20px rgba(26,107,74,0.04)",
    },
    blue: {
      background: "rgba(37,99,168,0.04)",
      border: "1px solid rgba(91,160,212,0.12)",
      boxShadow: "0 4px 20px rgba(37,99,168,0.04)",
    },
    glow: {
      background: "rgba(255,255,255,0.52)",
      border: "1px solid rgba(255,255,255,0.75)",
      boxShadow: "0 8px 32px rgba(45,139,85,0.06), 0 4px 16px rgba(124,58,237,0.04), inset 0 1px 0 rgba(255,255,255,0.5)",
    },
  };
  const v = variants[variant] || variants.default;
  return (
    <div style={{
      ...v, backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)",
      borderRadius: 16, padding: 28, ...style,
    }}>{children}</div>
  );
}

function Swatch({ color, name, hex, dark }) {
  return (
    <div style={{ textAlign: "center", flex: "0 0 62px" }}>
      <div style={{
        width: 44, height: 44, borderRadius: 11, background: color, margin: "0 auto 4px",
        border: `1px solid ${dark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.04)"}`,
        boxShadow: "0 2px 6px rgba(0,0,0,0.05), inset 0 1px 0 rgba(255,255,255,0.25)",
      }} />
      <div style={{ fontSize: 8.5, fontWeight: 600, color: dark ? C.nightText : C.text }}>{name}</div>
      <div style={{ fontSize: 7, color: dark ? C.nightMuted : C.textMuted, marginTop: 1 }}>{hex}</div>
    </div>
  );
}

function Label({ children, color, blue }) {
  return <div style={{ fontSize: 8.5, fontWeight: 600, letterSpacing: 2.5, color: color || (blue ? C.skyDeep : C.emerald), textTransform: "uppercase", marginBottom: 12 }}>{children}</div>;
}

